double SamplerState::AdjustedLogit(TokenId token, float logit) const noexcept {
#if LIE_C17_SAMPLING
  const auto counts = history_.penalties();
  const auto found = std::ranges::lower_bound(counts, token, {}, &TokenPenalty::token);
  const double bias = token < config_.logit_bias.size() ? config_.logit_bias[token] : 0.0;
  return bias + (found == counts.end() || found->token != token
      ? static_cast<double>(logit)
      : lie_sampling_penalize(logit, config_.repeat_penalty,
          config_.frequency_penalty, config_.presence_penalty,
          found->repeated, found->generated_count));
#else
  const auto found = std::ranges::lower_bound(penalty_counts_, token, {},
                                              &TokenPenalty::token);
  const double bias = token < config_.logit_bias.size() ? config_.logit_bias[token] : 0.0;
  return bias + (found == penalty_counts_.end() || found->token != token
             ? static_cast<double>(logit)
             : Penalize(logit, config_, *found));
#endif
}
